package com.club.controller;
import com.club.dto.*; import com.club.enumeration.MedioPago; import com.club.service.*; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.mvc.support.RedirectAttributes; import java.time.YearMonth; import java.util.List;
@RestController @RequestMapping("/api/pagos") @RequiredArgsConstructor class PagoRestController { private final PagoService service; @GetMapping public List<PagoResponse> listar(){return service.listarTodos();} @PostMapping("/{id}/anular") public PagoResponse anular(@PathVariable String id){service.anular(id);return service.obtener(id);} }
@Controller @RequestMapping("/pagos") @RequiredArgsConstructor public class PagoController { private final PagoService pago; private final FamiliaService familia; @GetMapping public String listar(Model m){m.addAttribute("pagos",pago.listarTodos());return "pagos/lista";} @GetMapping("/nuevo") public String nuevo(@RequestParam(required=false) String familiaId,Model m){PagoForm f=new PagoForm();f.setPeriodo(YearMonth.now().toString());m.addAttribute("form",f);m.addAttribute("familias",familia.listar());m.addAttribute("medioPagos",MedioPago.values());m.addAttribute("familiaIdSeleccionada",familiaId);return "pagos/form";} @PostMapping public String registrar(PagoForm f,@RequestParam String familiaId,Model m,RedirectAttributes ra){try{pago.registrarPago(familiaId,new RegistrarPagoDTO(f.getPeriodo(),f.getImporte(),f.getMedioPago(),f.getReferencia()));ra.addFlashAttribute("ok","Pago registrado correctamente.");return "redirect:/familias/"+familiaId;}catch(RuntimeException e){m.addAttribute("error",e.getMessage());m.addAttribute("familias",familia.listar());m.addAttribute("medioPagos",MedioPago.values());m.addAttribute("familiaIdSeleccionada",familiaId);m.addAttribute("form",f);return "pagos/form";}} @PostMapping("/{id}/anular") public String anular(@PathVariable String id,RedirectAttributes ra){try{pago.anular(id);ra.addFlashAttribute("ok","Pago anulado.");}catch(RuntimeException e){ra.addFlashAttribute("error",e.getMessage());}return "redirect:/pagos";} }
